contracts/PaymentSplitter.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title PaymentSplitter
 * @notice Receives USDC payments from agents, splits automatically:
 *         - 95% to the endpoint publisher
 *         - 5% to the AgentGate platform
 *
 *         The platform fee % is configurable by the owner.
 *         Publishers register their wallet address per endpoint.
 */
contract PaymentSplitter is Ownable {
    IERC20 public immutable usdc;
    address public platformWallet;
    uint16 public platformFeeBps; // basis points: 500 = 5%

    /// @notice Trusted PublisherRegistry allowed to call registerPublisher.
    ///         Set by owner via setRegistryAddress after deployment.
    ///         (R2-H: hardens against anyone claiming an unregistered endpoint.)
    address public registryAddress;

    // endpointId → publisher wallet
    mapping(uint256 => address) public endpointPublisher;

    // Track revenue
    mapping(uint256 => uint256) public endpointRevenue;     // total USDC received per endpoint
    mapping(address => uint256) public publisherEarnings;   // total USDC earned per publisher
    uint256 public totalPlatformRevenue;
    uint256 public totalPayments;

    event PaymentReceived(
        uint256 indexed endpointId,
        address indexed agent,
        uint256 total,
        uint256 publisherAmount,
        uint256 platformAmount
    );
    event PublisherRegistered(uint256 indexed endpointId, address indexed publisher);
    event PlatformFeeUpdated(uint16 oldBps, uint16 newBps);
    event PlatformWalletUpdated(address oldWallet, address newWallet);
    event RegistryAddressUpdated(address oldRegistry, address newRegistry);

    constructor(
        address _usdc,
        address _platformWallet,
        uint16 _platformFeeBps
    ) Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC address");
        require(_platformWallet != address(0), "Invalid platform wallet");
        require(_platformFeeBps <= 2000, "Fee too high (max 20%)");
        usdc = IERC20(_usdc);
        platformWallet = _platformWallet;
        platformFeeBps = _platformFeeBps;
    }

    /**
     * @notice Register (or rotate) the publisher wallet for an endpoint.
     *
     *         R2-H: previously anyone could call this for an unregistered
     *         endpoint (first-writer-wins), which meant an attacker could
     *         front-run a legitimate publisher and claim future payments.
     *         Now this is restricted to:
     *           - the trusted PublisherRegistry (configured via setRegistryAddress)
     *           - the current publisher (for self-rotation)
     *           - the contract owner (emergency override)
     *
     *         Unregistered endpoints stay unregistered until the Registry
     *         calls through during registerEndpoint().
     */
    function registerPublisher(uint256 endpointId, address publisher) external {
        require(publisher != address(0), "Invalid publisher");
        address current = endpointPublisher[endpointId];
        require(
            msg.sender == registryAddress ||
            msg.sender == owner() ||
            (current != address(0) && msg.sender == current),
            "Only Registry or current publisher"
        );
        endpointPublisher[endpointId] = publisher;
        emit PublisherRegistered(endpointId, publisher);
    }

    /**
     * @notice Set the trusted PublisherRegistry contract allowed to call
     *         registerPublisher. Owner-only. Pass address(0) to unset.
     */
    function setRegistryAddress(address newRegistry) external onlyOwner {
        emit RegistryAddressUpdated(registryAddress, newRegistry);
        registryAddress = newRegistry;
    }

    /**
     * @notice Pay for an API call. Agent approves USDC, then calls this.
     *         Splits: (100% - fee) to publisher, fee to platform.
     *
     * @param endpointId  The endpoint being called
     * @param amount      Total USDC amount (6 decimals)
     */
    function pay(uint256 endpointId, uint256 amount) external {
        require(amount > 0, "Zero amount");
        address publisher = endpointPublisher[endpointId];
        require(publisher != address(0), "Endpoint not registered");

        uint256 platformAmount = (amount * platformFeeBps) / 10000;
        uint256 publisherAmount = amount - platformAmount;

        // Transfer from agent to publisher + platform in one tx
        require(usdc.transferFrom(msg.sender, publisher, publisherAmount), "Publisher transfer failed");
        if (platformAmount > 0) {
            require(usdc.transferFrom(msg.sender, platformWallet, platformAmount), "Platform transfer failed");
        }

        endpointRevenue[endpointId] += amount;
        publisherEarnings[publisher] += publisherAmount;
        totalPlatformRevenue += platformAmount;
        totalPayments += 1;

        emit PaymentReceived(endpointId, msg.sender, amount, publisherAmount, platformAmount);
    }

    // ── Admin functions ────────────────────────────────────────────────────────

    function setPlatformFee(uint16 newBps) external onlyOwner {
        require(newBps <= 2000, "Fee too high (max 20%)");
        emit PlatformFeeUpdated(platformFeeBps, newBps);
        platformFeeBps = newBps;
    }

    function setPlatformWallet(address newWallet) external onlyOwner {
        require(newWallet != address(0), "Invalid wallet");
        emit PlatformWalletUpdated(platformWallet, newWallet);
        platformWallet = newWallet;
    }

    // ── View helpers ───────────────────────────────────────────────────────────

    function getPaymentBreakdown(uint256 amount) external view returns (
        uint256 publisherAmount,
        uint256 platformAmount
    ) {
        platformAmount = (amount * platformFeeBps) / 10000;
        publisherAmount = amount - platformAmount;
    }
}

contracts/PublisherRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title PublisherRegistry
 * @notice Registry for API publishers and their x402-protected endpoints.
 *         Publishers pay a one-time USDC publishing fee to register an endpoint.
 */
/// @notice Minimal interface for the PaymentSplitter hook.
interface IPaymentSplitter {
    function registerPublisher(uint256 endpointId, address publisher) external;
}

contract PublisherRegistry is Ownable {
    IERC20 public immutable usdc;
    address public platformWallet;
    uint256 public publishingFee; // USDC 6 decimals (e.g. 1_000_000 = 1 USDC)

    /// @notice Optional PaymentSplitter address. When set, registerEndpoint
    ///         forwards publisher claims to it so nobody else can claim the
    ///         endpoint's future payments (R2-H).
    address public paymentSplitter;
    struct Endpoint {
        uint256 id;
        address publisher;
        string url;
        uint256 pricePerCall; // USD quote, 6 decimals ($0.01 = 10000); off-chain settles in HBAR
        address paymasterAddress; // 0x0 if no paymaster
        bool isActive;
        uint256 totalCalls;
        uint256 totalRevenue;
        uint256 createdAt;
        bool requireWorldId; // if true, only WorldID-verified agents can access
    }

    uint256 public nextEndpointId;
    mapping(uint256 => Endpoint) public endpoints;
    mapping(address => uint256[]) public publisherEndpoints;

    /// @notice Address allowed to call recordCall (set to server/relayer wallet by owner).
    address public trustedCaller;

    // Events
    event EndpointRegistered(
        uint256 indexed id,
        address indexed publisher,
        string url,
        uint256 pricePerCall,
        address paymasterAddress
    );
    event EndpointDeactivated(uint256 indexed id, address indexed publisher);
    event EndpointActivated(uint256 indexed id, address indexed publisher);
    event WorldIdRequirementSet(uint256 indexed id, bool required);
    event PaymasterUpdated(uint256 indexed id, address paymasterAddress);
    event CallRecorded(uint256 indexed id, address indexed caller, uint256 revenue);
    event PublishingFeePaid(uint256 indexed id, address indexed publisher, uint256 amount);
    event PublishingFeeUpdated(uint256 oldFee, uint256 newFee);
    event PlatformWalletUpdated(address oldWallet, address newWallet);
    event PaymentSplitterUpdated(address oldSplitter, address newSplitter);

    constructor(address _usdc, address _platformWallet, uint256 _publishingFee) Ownable(msg.sender) {
        require(_usdc != address(0), "Invalid USDC");
        require(_platformWallet != address(0), "Invalid platform wallet");
        usdc = IERC20(_usdc);
        platformWallet = _platformWallet;
        publishingFee = _publishingFee;
    }

    /// @notice Authorize a server/relayer address to call recordCall.
    function setTrustedCaller(address _caller) external onlyOwner {
        trustedCaller = _caller;
    }

    /// @notice Configure the PaymentSplitter that tracks publisher-of-record
    ///         per endpoint. Owner-only. Pass address(0) to disable the hook.
    function setPaymentSplitter(address _splitter) external onlyOwner {
        emit PaymentSplitterUpdated(paymentSplitter, _splitter);
        paymentSplitter = _splitter;
    }

    modifier onlyPublisher(uint256 endpointId) {
        require(endpoints[endpointId].publisher == msg.sender, "Not endpoint publisher");
        _;
    }

    /**
     * @notice Register a new API endpoint. Requires paying `publishingFee` in USDC.
     *         Caller must first approve USDC spending to this contract.
     * @param url The API endpoint URL
     * @param pricePerCall USD amount, 6 decimals ($0.01 = 10000); settled in USDC
     * @param paymasterAddress Address of the Paymaster (0x0 if none)
     */
    function registerEndpoint(
        string calldata url,
        uint256 pricePerCall,
        address paymasterAddress
    ) external returns (uint256 id) {
        // Collect publishing fee (if > 0)
        if (publishingFee > 0) {
            require(
                usdc.transferFrom(msg.sender, platformWallet, publishingFee),
                "Publishing fee transfer failed"
            );
        }

        id = nextEndpointId++;

        endpoints[id] = Endpoint({
            id: id,
            publisher: msg.sender,
            url: url,
            pricePerCall: pricePerCall,
            paymasterAddress: paymasterAddress,
            isActive: true,
            totalCalls: 0,
            totalRevenue: 0,
            createdAt: block.timestamp,
            requireWorldId: false
        });

        publisherEndpoints[msg.sender].push(id);

        // R2-H: forward the publisher claim to the splitter if configured, so
        // only this Registry (not arbitrary callers) can bind an endpoint to
        // a publisher wallet on the splitter.
        if (paymentSplitter != address(0)) {
            IPaymentSplitter(paymentSplitter).registerPublisher(id, msg.sender);
        }

        emit EndpointRegistered(id, msg.sender, url, pricePerCall, paymasterAddress);
        if (publishingFee > 0) {
            emit PublishingFeePaid(id, msg.sender, publishingFee);
        }
    }

    /// @notice Update the publishing fee (owner only).
    function setPublishingFee(uint256 newFee) external onlyOwner {
        emit PublishingFeeUpdated(publishingFee, newFee);
        publishingFee = newFee;
    }

    /// @notice Update the platform wallet that receives publishing fees.
    function setPlatformWallet(address newWallet) external onlyOwner {
        require(newWallet != address(0), "Invalid wallet");
        emit PlatformWalletUpdated(platformWallet, newWallet);
        platformWallet = newWallet;
    }

    /**
     * @notice Deactivate an endpoint
     */
    function deactivateEndpoint(uint256 endpointId) external onlyPublisher(endpointId) {
        require(endpoints[endpointId].isActive, "Already inactive");
        endpoints[endpointId].isActive = false;
        emit EndpointDeactivated(endpointId, msg.sender);
    }

    /**
     * @notice Reactivate an endpoint
     */
    function activateEndpoint(uint256 endpointId) external onlyPublisher(endpointId) {
        require(!endpoints[endpointId].isActive, "Already active");
        endpoints[endpointId].isActive = true;
        emit EndpointActivated(endpointId, msg.sender);
    }

    /**
     * @notice Update the paymaster address for an endpoint
     */
    function updatePaymaster(uint256 endpointId, address paymasterAddress) external onlyPublisher(endpointId) {
        endpoints[endpointId].paymasterAddress = paymasterAddress;
        emit PaymasterUpdated(endpointId, paymasterAddress);
    }

    /**
     * @notice Set WorldID requirement for an endpoint
     */
    function setRequireWorldId(uint256 endpointId, bool required) external onlyPublisher(endpointId) {
        endpoints[endpointId].requireWorldId = required;
        emit WorldIdRequirementSet(endpointId, required);
    }

    /**
     * @notice Record a successful API call. Only callable by owner or the designated
     *         trustedCaller (server/relayer). Public access was a griefable stat inflation vector.
     */
    function recordCall(uint256 endpointId) external {
        require(
            msg.sender == owner() || msg.sender == trustedCaller,
            "recordCall: not authorized"
        );
        require(endpoints[endpointId].isActive, "Endpoint inactive");
        endpoints[endpointId].totalCalls += 1;
        endpoints[endpointId].totalRevenue += endpoints[endpointId].pricePerCall;
        emit CallRecorded(endpointId, msg.sender, endpoints[endpointId].pricePerCall);
    }

    /**
     * @notice Get endpoint details
     */
    function getEndpoint(uint256 endpointId) external view returns (Endpoint memory) {
        return endpoints[endpointId];
    }

    /**
     * @notice Get all endpoint IDs for a publisher
     */
    function getPublisherEndpoints(address publisher) external view returns (uint256[] memory) {
        return publisherEndpoints[publisher];
    }

    /**
     * @notice Get total number of endpoints
     */
    function getTotalEndpoints() external view returns (uint256) {
        return nextEndpointId;
    }

    /**
     * @notice Check if an endpoint has a paymaster (sponsored gas)
     */
    function isSponsored(uint256 endpointId) external view returns (bool) {
        return endpoints[endpointId].paymasterAddress != address(0) && endpoints[endpointId].isActive;
    }
}

contracts/ReviewRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title ReviewRegistry
 * @notice On-chain rating system for AgentGate endpoints and publishers.
 *
 *         Anti-sybil: only addresses verified through the trusted relayer can rate.
 *         The relayer (AgentGate server) verifies WorldID before submitting ratings,
 *         ensuring 1 real human = 1 vote per endpoint.
 *
 *         - Each agent can rate each endpoint once (update allowed, not delete)
 *         - Score: 1-5 (stars)
 *         - Optional comment hash (IPFS CID or keccak of comment stored off-chain)
 *         - Publisher reputation = average across all their endpoints
 */
contract ReviewRegistry is Ownable {

    struct Review {
        address reviewer;
        uint256 endpointId;
        uint8 score;            // 1-5
        bytes32 commentHash;    // optional
        uint256 timestamp;
    }

    /// @notice Trusted relayer that submits WorldID-verified ratings
    address public trustedRelayer;

    // endpointId → list of reviews
    mapping(uint256 => Review[]) public endpointReviews;

    // endpointId → reviewer → index in array (for update)
    mapping(uint256 => mapping(address => uint256)) private reviewIndex;
    mapping(uint256 => mapping(address => bool)) public hasReviewed;

    // Aggregate stats
    mapping(uint256 => uint256) public endpointTotalScore;
    mapping(uint256 => uint256) public endpointReviewCount;
    mapping(address => uint256) public publisherTotalScore;
    mapping(address => uint256) public publisherReviewCount;

    event ReviewSubmitted(
        uint256 indexed endpointId,
        address indexed reviewer,
        address indexed publisher,
        uint8 score,
        bytes32 commentHash
    );

    event ReviewUpdated(
        uint256 indexed endpointId,
        address indexed reviewer,
        uint8 oldScore,
        uint8 newScore
    );

    constructor() Ownable(msg.sender) {}

    function setTrustedRelayer(address _relayer) external onlyOwner {
        trustedRelayer = _relayer;
    }

    /**
     * @notice Submit a WorldID-verified rating. Only callable by the trusted relayer
     *         or the reviewer directly (for decentralized fallback).
     *
     * @param reviewer    The agent wallet (verified by relayer via WorldID)
     * @param endpointId  The endpoint to rate
     * @param publisher   The publisher address
     * @param score       Rating 1-5
     * @param commentHash Optional comment hash
     */
    function rateVerified(
        address reviewer,
        uint256 endpointId,
        address publisher,
        uint8 score,
        bytes32 commentHash
    ) external {
        require(msg.sender == trustedRelayer || msg.sender == owner(), "Only trusted relayer");
        require(score >= 1 && score <= 5, "Score must be 1-5");
        require(reviewer != publisher, "Cannot rate your own endpoint");

        _submitRating(reviewer, endpointId, publisher, score, commentHash);
    }

    // R2-I: the public `rate()` function was removed. It allowed unlimited
    // sybil ratings (1 wallet = 1 rating, but wallet creation is free), which
    // defeated the anti-sybil purpose of the registry. Ratings must go
    // through rateVerified() from the trusted relayer, which gates on
    // WorldID so each real human can only rate an endpoint once.

    function _submitRating(
        address reviewer,
        uint256 endpointId,
        address publisher,
        uint8 score,
        bytes32 commentHash
    ) internal {
        if (hasReviewed[endpointId][reviewer]) {
            // Update existing
            uint256 idx = reviewIndex[endpointId][reviewer];
            Review storage existing = endpointReviews[endpointId][idx];
            uint8 oldScore = existing.score;

            endpointTotalScore[endpointId] = endpointTotalScore[endpointId] - oldScore + score;
            publisherTotalScore[publisher] = publisherTotalScore[publisher] - oldScore + score;

            existing.score = score;
            existing.commentHash = commentHash;
            existing.timestamp = block.timestamp;

            emit ReviewUpdated(endpointId, reviewer, oldScore, score);
        } else {
            // New review
            uint256 idx = endpointReviews[endpointId].length;
            endpointReviews[endpointId].push(Review({
                reviewer: reviewer,
                endpointId: endpointId,
                score: score,
                commentHash: commentHash,
                timestamp: block.timestamp
            }));

            reviewIndex[endpointId][reviewer] = idx;
            hasReviewed[endpointId][reviewer] = true;

            endpointTotalScore[endpointId] += score;
            endpointReviewCount[endpointId] += 1;
            publisherTotalScore[publisher] += score;
            publisherReviewCount[publisher] += 1;

            emit ReviewSubmitted(endpointId, reviewer, publisher, score, commentHash);
        }
    }

    // ── View helpers ───────────────────────────────────────────────────────────

    function endpointAvgRating(uint256 endpointId) external view returns (uint256) {
        if (endpointReviewCount[endpointId] == 0) return 0;
        return (endpointTotalScore[endpointId] * 100) / endpointReviewCount[endpointId];
    }

    function publisherAvgRating(address publisher) external view returns (uint256) {
        if (publisherReviewCount[publisher] == 0) return 0;
        return (publisherTotalScore[publisher] * 100) / publisherReviewCount[publisher];
    }

    function getEndpointReviews(uint256 endpointId) external view returns (Review[] memory) {
        return endpointReviews[endpointId];
    }

    function getReviewCount(uint256 endpointId) external view returns (uint256) {
        return endpointReviewCount[endpointId];
    }
}

